mapper.select:
select
count(distinct lbc.id)
from logistics_bill_cost lbc

    ${params.sqlMap.default}
    and lbc.is_deleted = false


        AND lb.order_type not in

            #{item}



        ${params.permissionSql}

select lbc.id, lb.order_type as orderType, lb.source_type as sourceType, lbc.reconciliation_status as reconciliationStatus, lc.name as channelName, lbc.transport_no as transportNo, lbc.track_no as trackNo, lbc.channel_id as channelId, lbc.logistics_bill_detail_id, lbd.transportStatus, lbc.actual_weight as actualWeight, lbc.volume_weight as volumeWeight, lbc.billing_weight as billingWeight, lbc.estimated_shipping_cost as estimatedShippingCost, lbc.billing_weight_logistics as billingWeightLogistics, lbc.actual_shipping_cost as actualShippingCost, lbc.diff_shipping_cost as diffShippingCost, lb.sales_platform as salesPlatform, lb.source_id as sourceId, lb.source_code as sourceCode, lb.outstock_code as outstockCode, lb.to_country as toCountry, lb.shop_name as customerName, lb.order_time as orderTime, lb.delivery_time as deliveryTime, lbc.remark, lbc.weight_unit as weightUnit, lbc.currency, lb.platform_code as platformCode, lbc.fee_rule, lbc.confirm_time as confirmTime, lbc.shop_charge_id, lbc.volume, lbc.pay_type, lbc.pay_status, lbc.pay_time, lbc.check_status from logistics_bill_cost lbc inner join logistics_bill lb on lbc.logistics_bill_id = lb.id and lb.is_deleted = false left join ( select main_id,max(track_status) as transportStatus from logistics_bill_detail where is_deleted = false group by main_id ) lbd on lb.id = lbd.main_id left join logistics_channel lc on lbc.channel_id = lc.id and lc.is_deleted = false
${params.sqlMap.default} and lbc.is_deleted = false
${params.permissionSql}
ORDER BY
${item.field} ${item.sort}
lbc.id desc

select lbc.id, lb.order_type as orderType, lb.source_type as sourceType, lbc.reconciliation_status as reconciliationStatus, lc.name as channelName, lbc.track_no, lbc.logistics_bill_detail_id, lbc.transport_no as transportNo, lbd.transportStatus, lbc.actual_weight as actualWeight, lbc.volume_weight as volumeWeight, lbc.billing_weight as billingWeight, lbc.estimated_shipping_cost as estimatedShippingCost, lbc.billing_weight_logistics as billingWeightLogistics, lbc.actual_shipping_cost as actualShippingCost, lbc.diff_shipping_cost as diffShippingCost, lb.sales_platform as salesPlatform, lb.source_id as sourceId, lb.source_code as sourceCode, lb.outstock_code as outstockCode, lb.to_country as toCountry, lb.shop_name as customerName, lb.order_time as orderTime, lb.delivery_time as deliveryTime, lbc.remark, lbc.weight_unit as weightUnit, lbc.currency, lb.platform_code as platformCode, lbc.fee_rule as feeRule, lbc.confirm_time as confirmTime, lbc.shop_charge_id, lbc.shop_charge_name from logistics_bill_cost lbc inner join logistics_bill lb on lbc.logistics_bill_id = lb.id and lb.is_deleted = false left join ( select main_id,max(track_status) as transportStatus from logistics_bill_detail where is_deleted = false group by main_id ) lbd on lb.id = lbd.main_id left join logistics_channel lc on lbc.channel_id = lc.id and lc.is_deleted = false
${params.sqlMap.default} and lbc.is_deleted = false
${params.permissionSql}
ORDER BY
${item.field} ${item.sort}
lbc.id desc

SELECT b.outstock_id AS outstockId, b.outstock_code AS outstockCode, b.transport_no AS transportNo, c.reconciliation_status AS reconciliationStatus FROM logistics_bill AS b LEFT JOIN logistics_bill_cost AS c ON b.ID = c.logistics_bill_id AND c.is_deleted = FALSE WHERE b.is_deleted = FALSE
AND b.outstock_id IN
#{item}
